  assert.equal(totals.voucher, 0);
});

test('applyVoucher adds voucher to draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);

  const result = applyVoucher(invoice.value, { code: 'SAVE10', amount: 5000 });
  assert.equal(result.ok, true);
  assert.equal(result.value.voucher.code, 'SAVE10');
  assert.equal(result.value.voucher.amount, 5000);
});

test('invoiceTotals deducts voucher from total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);

  const totals1 = invoiceTotals(invoice.value);
  const totalBefore = totals1.total;

  const vouchered = applyVoucher(invoice.value, { code: 'SAVE10', amount: 5000 });
  assert.equal(vouchered.ok, true);

  const totals2 = invoiceTotals(vouchered.value);
  assert.equal(totals2.voucher, 5000);
  assert.equal(totals2.total, totalBefore - 5000);
});

test('invoiceTotals clamps total at 0 when voucher exceeds subtotal + vat', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);

  const totals = invoiceTotals(invoice.value);
  const largeVoucher = totals.total + 100000;

  const vouchered = applyVoucher(invoice.value, { code: 'SAVE', amount: largeVoucher });
  assert.equal(vouchered.ok, true);

  const totals2 = invoiceTotals(vouchered.value);
  assert.equal(totals2.total, 0);
});

test('applyVoucher rejects non-draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);

  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);

  const result = applyVoucher(issued.value, { code: 'SAVE10', amount: 5000 });
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('applyVoucher rejects when voucher already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);

  const result1 = applyVoucher(invoice.value, { code: 'SAVE10', amount: 5000 });
  assert.equal(result1.ok, true);

  const result2 = applyVoucher(result1.value, { code: 'SAVE20', amount: 10000 });
  assert.deepEqual(result2, { ok: false, error: 'VOUCHER_EXISTS' });
});

test('applyVoucher rejects zero amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);

  const result = applyVoucher(invoice.value, { code: 'SAVE10', amount: 0 });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('applyVoucher rejects negative amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);

  const result = applyVoucher(invoice.value, { code: 'SAVE10', amount: -5000 });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('applyVoucher rejects non-integer amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);

  const result = applyVoucher(invoice.value, { code: 'SAVE10', amount: 5000.5 });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('addLine preserves voucher on draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);

  const vouchered = applyVoucher(invoice.value, { code: 'SAVE10', amount: 5000 });
  assert.equal(vouchered.ok, true);

  const result = addLine(vouchered.value, { sku: 'DEV-HOUR', qty: 2 });
  assert.equal(result.ok, true);
  assert.equal(result.value.voucher.code, 'SAVE10');
  assert.equal(result.value.voucher.amount, 5000);
});

test('removeLine preserves voucher on draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'DEV-HOUR', qty: 2 },
    ],
  });
  assert.equal(invoice.ok, true);

  const vouchered = applyVoucher(invoice.value, { code: 'SAVE10', amount: 5000 });
  assert.equal(vouchered.ok, true);

  const result = removeLine(vouchered.value, 'DEV-HOUR');
  assert.equal(result.ok, true);
  assert.equal(result.value.voucher.code, 'SAVE10');
  assert.equal(result.value.voucher.amount, 5000);
});

test('issueInvoice preserves voucher', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);

  const vouchered = applyVoucher(invoice.value, { code: 'SAVE10', amount: 5000 });
  assert.equal(vouchered.ok, true);

  const issued = issueInvoice(vouchered.value, []);
  assert.equal(issued.ok, true);
  assert.equal(issued.value.voucher.code, 'SAVE10');
  assert.equal(issued.value.voucher.amount, 5000);
});

test('applyVoucher does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);

  const originalVoucher = invoice.value.voucher;

  applyVoucher(invoice.value, { code: 'SAVE10', amount: 5000 });

  assert.equal(invoice.value.voucher, originalVoucher);
});

